/* ============================================================
   小说感排版 · 酒馆助手（Tavern Helper / JS-Slash-Runner）脚本
   ------------------------------------------------------------
   在“显示层”把正文排成小说感：首行缩进 + 段间空行，单换行也能
   分段。只改当前显示，不修改聊天记录、不污染上下文、不用正则。

   ★ 全面适配主题美化：
   - 段落样式用【内联 !important】写入，优先级最高，
     绝大多数 CSS 美化预设都无法覆盖（解决“完全没反应”）；
   - 幂等重排：编辑/重抽/切换聊天后都会正确重新排版；
   - MutationObserver 兜底，兼容会重新渲染楼层 / 懒加载的主题；
   - 自动跳过 <details> 折叠块、代码、引用、表格、列表、卡片
     (div) 与 HTML 注释，隐藏草稿与美化卡片都不会被破坏。

   关键：酒馆助手脚本运行在 iframe 沙箱里，必须通过
   retrieveDisplayedMessage() 取楼层、用 window.parent 访问主界面。

   用法：酒馆助手 → 脚本库 → 导入本 JSON → 启用。
   调整：打开脚本，改 content 顶部 CONFIG。
   ============================================================ */

(function () {
  'use strict';

  // ===== 可调配置 =====
  const CONFIG = {
    indent:     '2em',    // 首行缩进，设为 '0' 可取消缩进
    paraGap:    '0.9em',  // 段间距，数值越大空行感越强
    lineHeight: '1.85',   // 行距
    formatUser: false,    // 是否也排版“你发出的消息”
  };

  // 主界面（父窗口）document —— 脚本运行在 iframe 内
  const pdoc = window.parent.document;
  const STYLE_ID = 'novel-format-style';

  // 这些块级内容原样保留，不参与正文分段/缩进（保护美化卡片、代码等）
  const SKIP_TAGS = new Set([
    'DETAILS', 'PRE', 'CODE', 'BLOCKQUOTE', 'TABLE', 'THEAD', 'TBODY',
    'TR', 'TD', 'TH', 'UL', 'OL', 'LI', 'HR', 'IMG', 'FIGURE',
    'VIDEO', 'AUDIO', 'IFRAME', 'DIV', 'CANVAS', 'SVG',
  ]);

  // 给段落写【内联 + !important】样式：优先级最高，主题 CSS 难以覆盖
  function styleParagraph(p) {
    p.classList.add('novel-para');
    const s = p.style;
    s.setProperty('display', 'block', 'important');
    s.setProperty('text-indent', CONFIG.indent, 'important');
    s.setProperty('margin', '0 0 ' + CONFIG.paraGap, 'important');
    s.setProperty('line-height', CONFIG.lineHeight, 'important');
    s.setProperty('white-space', 'normal', 'important');
  }

  // 兜底样式（内联样式才是主力，这里只是双保险）
  function injectStyle() {
    const old = pdoc.getElementById(STYLE_ID);
    if (old) old.remove();
    const s = pdoc.createElement('style');
    s.id = STYLE_ID;
    s.textContent =
      `#chat .mes_text p.novel-para{` +
      `display:block!important;` +
      `text-indent:${CONFIG.indent}!important;` +
      `margin:0 0 ${CONFIG.paraGap}!important;` +
      `line-height:${CONFIG.lineHeight}!important;` +
      `white-space:normal!important;}` +
      `#chat .mes_text p.novel-para:last-child{margin-bottom:0!important;}`;
    pdoc.head.appendChild(s);
  }

  // 判断某个 .mes_text 是否已经是排好的状态（幂等用，防止重复重排/死循环）
  function isFormatted(root) {
    for (const node of root.childNodes) {
      if (node.nodeType === 8) continue;                       // 注释
      if (node.nodeType === 3) {                               // 顶层裸文本 => 未排版
        if (node.textContent && node.textContent.trim()) return false;
        continue;
      }
      if (node.nodeType === 1) {
        const tag = node.tagName;
        if (tag === 'P' || SKIP_TAGS.has(tag)) continue;       // 段落或被保护块
        return false;                                          // BR / 顶层内联元素 => 未排版
      }
    }
    return true;
  }

  // 把单个 .mes_text 容器内的正文重组为段落
  function formatRoot(root) {
    if (!root || isFormatted(root)) return;

    const frag = pdoc.createDocumentFragment();
    let buf = [];

    const flush = () => {
      const hasContent = buf.some(
        (n) => n.nodeType === 1 || (n.textContent && n.textContent.trim())
      );
      if (!hasContent) { buf = []; return; }
      const p = pdoc.createElement('p');
      styleParagraph(p);
      buf.forEach((n) => p.appendChild(n));
      frag.appendChild(p);
      buf = [];
    };

    Array.from(root.childNodes).forEach((node) => {
      if (node.nodeType === 8) { flush(); frag.appendChild(node); return; } // 注释保留

      if (node.nodeType === 1) {
        const tag = node.tagName;
        if (tag === 'BR') { flush(); return; }                 // 换行 => 分段
        if (tag === 'P') { flush(); styleParagraph(node); frag.appendChild(node); return; }
        if (SKIP_TAGS.has(tag)) { flush(); frag.appendChild(node); return; }
        buf.push(node);                                         // 内联元素
        return;
      }

      if (node.nodeType === 3) {                                // 文本按换行拆段
        const parts = node.textContent.split('\n');
        parts.forEach((part, i) => {
          if (i > 0) flush();
          if (part) buf.push(pdoc.createTextNode(part));
        });
        return;
      }

      buf.push(node);
    });

    flush();
    root.innerHTML = '';
    root.appendChild(frag);

    // 末段去掉底部多余间距
    const paras = root.querySelectorAll(':scope > p.novel-para');
    if (paras.length) {
      paras[paras.length - 1].style.setProperty('margin-bottom', '0', 'important');
    }
  }

  // 排版单条楼层（事件回调，content 已变化，直接重排）
  function formatMessage(message_id) {
    if (message_id === undefined || message_id === null) return;
    let $mes;
    try { $mes = retrieveDisplayedMessage(message_id); } catch (e) { return; }
    if (!$mes || $mes.length === 0) return;
    if (!CONFIG.formatUser && $mes.closest('.mes').attr('is_user') === 'true') return;
    $mes.each((_, el) => formatRoot(el));
  }

  // 排版当前所有楼层
  function formatAll() {
    const sel = CONFIG.formatUser
      ? '#chat .mes .mes_text'
      : '#chat .mes[is_user="false"] .mes_text';
    pdoc.querySelectorAll(sel).forEach(formatRoot);
  }

  let timer = null;
  function scheduleAll() {
    clearTimeout(timer);
    timer = setTimeout(formatAll, 60);
  }

  injectStyle();

  // 渲染事件：渲染后排版对应楼层
  ['CHARACTER_MESSAGE_RENDERED', 'USER_MESSAGE_RENDERED'].forEach((name) => {
    try {
      if (typeof tavern_events !== 'undefined' && tavern_events[name]) {
        eventOn(tavern_events[name], formatMessage);
      }
    } catch (e) { /* 忽略 */ }
  });

  // 切换聊天 / 编辑 / 重抽 / 加载更多：全量排版
  ['CHAT_CHANGED', 'MORE_MESSAGES_LOADED', 'MESSAGE_EDITED', 'MESSAGE_SWIPED', 'MESSAGE_UPDATED'].forEach((name) => {
    try {
      if (typeof tavern_events !== 'undefined' && tavern_events[name]) {
        eventOn(tavern_events[name], scheduleAll);
      }
    } catch (e) { /* 忽略 */ }
  });

  // MutationObserver 兜底：兼容会重新渲染楼层 / 懒加载的主题。
  // 只观察 #chat 直接子级（不深入 subtree），避免逐字流式输出时反复重排。
  try {
    const chat = pdoc.querySelector('#chat');
    if (chat && typeof MutationObserver !== 'undefined') {
      new MutationObserver(scheduleAll).observe(chat, { childList: true });
    }
  } catch (e) { /* 忽略 */ }

  scheduleAll(); // 首次立即排版
})();
